func eventBreadcrumbs(snapshot Snapshot, section string, current string) []frontend.Breadcrumb {
	breadcrumbs := []frontend.Breadcrumb{
		{Label: "Events", Href: "/"},
		{Label: snapshot.EventName, Href: "/events/" + snapshot.EventSlug},
	}
	if current == "" {
		return append(breadcrumbs, frontend.Breadcrumb{Label: section})
	}
	return append(
		breadcrumbs,
		frontend.Breadcrumb{
			Label: section,
			Href:  "/events/" + snapshot.EventSlug + "/" + strings.ToLower(section),
		},
		frontend.Breadcrumb{Label: current},
	)
}

